def apply_unique(slug, p):
    u = UNIQUE.get(slug)
    if not u:
        return p
    for k, v in u.items():
        if k == "faqs_prepend":
            existing = [q for q, a in p.get("faqs", [])]
            p["faqs"] = [qa for qa in v if qa[0] not in existing] + list(p.get("faqs", []))
        else:
            p[k] = v
    return p
